//! Amino-acid substitution matrices (BLOSUM / PAM), ported verbatim from
//! rust-bio's `scores` module (data originally from SeqAn). Each function has
//! the `fn(u8, u8) i32` shape, so it doubles as a `MatchFunc` for the pairwise
//! aligner. Tables are indexed by a shared `lookup` over a 27-symbol space.
//!
//! This file is generated from rust-bio/src/scores/*.rs — see
//! scratchpad/gen_scores.py. Do not edit the tables by hand.

const std = @import("std");
const testing = std.testing;

/// Map an ASCII residue byte to its row/column index in the 27x27 matrices.
/// Mirrors rust-bio: Y->23, Z->24, X->25, '*'->26, otherwise (byte - 'A').
inline fn lookup(a: u8) usize {
    return switch (a) {
        'Y' => 23,
        'Z' => 24,
        'X' => 25,
        '*' => 26,
        else => @as(usize, a - 65),
    };
}

inline fn score(comptime mat: *const [27 * 27]i32, a: u8, b: u8) i32 {
    return mat[27 * lookup(a) + lookup(b)];
}

