test "blosum62 known values" {
    try testing.expectEqual(@as(i32, 8), blosum62('H', 'H'));
    try testing.expectEqual(@as(i32, -4), blosum62('O', '*'));
    try testing.expectEqual(@as(i32, -4), blosum62('A', '*'));
    try testing.expectEqual(@as(i32, 1), blosum62('*', '*'));
    try testing.expectEqual(@as(i32, -1), blosum62('X', 'X'));
    try testing.expectEqual(@as(i32, -1), blosum62('X', 'Z'));
    try testing.expectEqual(@as(i32, -2), blosum62('H', 'A'));
    try testing.expectEqual(@as(i32, 4), blosum62('A', 'A'));
}

test "blosum30 / blosum45 known values" {
    try testing.expectEqual(@as(i32, 4), blosum30('A', 'A'));
    try testing.expectEqual(@as(i32, 5), blosum45('A', 'A'));
}

test "pam matrices known values" {
    try testing.expectEqual(@as(i32, 6), pam40('A', 'A'));
    try testing.expectEqual(@as(i32, 3), pam120('A', 'A'));
    try testing.expectEqual(@as(i32, 3), pam200('A', 'A'));
    try testing.expectEqual(@as(i32, 2), pam250('A', 'A'));
}

test "substitution matrices are symmetric over the 20 standard residues" {
    const residues = "ARNDCQEGHILKMFPSTWYV";
    const fns = [_]*const fn (u8, u8) i32{
        &blosum30, &blosum45, &blosum62, &pam40, &pam120, &pam200, &pam250,
    };
    for (fns) |f| {
        for (residues) |a| {
            for (residues) |b| {
                try testing.expectEqual(f(a, b), f(b, a));
            }
        }
    }
}
